        if (worldTypes.contains(WorldType.TOURNAMENT_WORLD)) {
            return BankWorldType.TOURNAMENT;
        }
        if (worldTypes.contains(WorldType.DEADMAN)) {
            return BankWorldType.DEADMAN;
        }
        return BankWorldType.DEFAULT;
    }
